const base = (env.get('CRONUSFARM_SQLITE_BRIDGE_URL') || 'http://127.0.0.1:18766').toString().replace(/\/$/, '');
const u = (msg.req && msg.req.url) ? msg.req.url : '';
const q = u.indexOf('?') >= 0 ? u.slice(u.indexOf('?')) : '';
msg.method = 'GET';
